css:
*,*::before,*::after{box-sizing:border-box}
:root{
  --page:#f5f4f0;
  --chrome:#fbfaf7;
  --surface:#ffffff;
  --ink:#161815;
  --ink-2:#4e524c;
  --muted:#6b6f68;
  --line:#e5e2da;
  --line-strong:#d8d4ca;
  --grid:#eeece6;
  --axis:#d9d5cb;
  --brand:#2f6f5e;
  --brand-strong:#245747;
  --brand-tint:#eaf2ee;
  --good:#0e6a4a;
  --good-bg:#e8f4ed;
  --bad:#a13224;
  --bad-bg:#fbeae7;
  --radius:12px;
  --font:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  --mono:ui-monospace,SFMono-Regular,"SF Mono",Menlo,Consolas,"Liberation Mono",monospace;
}
html{-webkit-text-size-adjust:100%}
body{
  margin:0;
  background:var(--page);
  color:var(--ink);
  font-family:var(--font);
  font-size:14px;
  line-height:1.4;
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
}
a{color:inherit;text-decoration:none}
button{font:inherit;color:inherit}
svg{display:block}
::selection{background:#d7e7df;color:#10231c}
.sr-only{
  position:absolute;width:1px;height:1px;padding:0;margin:-1px;
  overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0;
}
.skip{
  position:fixed;left:16px;top:-60px;z-index:100;
  background:var(--ink);color:#fff;padding:9px 14px;border-radius:8px;
  font-size:12.5px;transition:top .15s ease;
}
.skip:focus{top:12px}
a:focus-visible,button:focus-visible{outline:2px solid var(--brand);outline-offset:2px}

.topbar{
  height:56px;display:flex;align-items:stretch;
  background:var(--chrome);
  border-bottom:1px solid var(--line);
  position:sticky;top:0;z-index:40;
}
.topbar-brand{
  width:228px;flex:none;display:flex;align-items:center;
  padding:0 20px;border-right:1px solid var(--line);
}
.brand{display:inline-flex;align-items:center;gap:9px;border-radius:7px}
.brand-mark{
  width:24px;height:24px;border-radius:7px;display:grid;place-items:center;color:#fff;
  background:linear-gradient(150deg,#3a806b,#255746);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.18),0 1px 2px rgba(22,24,21,.18);
}
.brand-mark svg{width:15px;height:15px}
.brand-name{font-size:15px;font-weight:600;letter-spacing:-.015em}
.topbar-tools{
  margin-left:auto;display:flex;align-items:center;gap:11px;
  padding:0 20px;
}
.range{
  display:inline-flex;align-items:center;gap:7px;height:34px;
  padding:0 10px 0 11px;background:var(--surface);
  border:1px solid var(--line-strong);border-radius:8px;
  font-size:12.5px;font-weight:500;color:var(--ink-2);cursor:pointer;
  box-shadow:0 1px 1px rgba(22,24,21,.03);
  transition:border-color .15s ease,background-color .15s ease;
  white-space:nowrap;
}
.range:hover{border-color:#c7c2b7;background:#fdfdfb}
.range .ico{width:14px;height:14px;color:var(--muted);flex:none}
.range .chev{width:11px;height:11px;color:var(--muted);flex:none;margin-left:1px}
.tool-divider{width:1px;height:20px;background:var(--line);margin:0 1px}
.avatar{
  position:relative;width:32px;height:32px;padding:0;border:0;border-radius:50%;
  background:none;cursor:pointer;flex:none;
  transition:box-shadow .15s ease;
}
.avatar:hover{box-shadow:0 0 0 3px var(--brand-tint)}
.avatar svg{width:32px;height:32px;border-radius:50%}
.presence{
  position:absolute;right:-1px;bottom:-1px;width:9px;height:9px;border-radius:50%;
  background:#3f9d78;border:2px solid var(--chrome);
}

.shell{display:flex;align-items:flex-start;min-height:calc(100vh - 56px)}
.sidebar{
  width:228px;flex:none;align-self:stretch;
  background:var(--chrome);border-right:1px solid var(--line);
  padding:14px 12px;
  position:sticky;top:56px;height:calc(100vh - 56px);overflow-y:auto;
}
.nav{display:flex;flex-direction:column;gap:2px;height:100%}
.nav-item{
  display:flex;align-items:center;gap:10px;
  padding:9px 10px;border-radius:8px;
  font-size:13px;font-weight:500;color:var(--ink-2);
  position:relative;
  transition:background-color .15s ease,color .15s ease;
}
.nav-item svg{width:17px;height:17px;flex:none;color:var(--muted);transition:color .15s ease}
.nav-item:hover{background:#f1efe9;color:var(--ink)}
.nav-item:hover svg{color:var(--ink-2)}
.nav-item.is-active{background:var(--brand-tint);color:var(--ink);font-weight:600}
.nav-item.is-active svg{color:var(--brand-strong)}
.nav-item.is-active:hover{background:#e3eee8}
.nav-item.is-active:hover svg{color:var(--brand-strong)}
.nav-item.is-active::before{
  content:"";position:absolute;left:0;top:9px;bottom:9px;width:2px;
  border-radius:2px;background:var(--brand);
}
.nav-settings{margin-top:auto}

.main{
  flex:1;min-width:0;min-height:calc(100vh - 56px);
  background:radial-gradient(900px 420px at 88% -8%,rgba(47,111,94,.055),transparent 62%),var(--page);
}
.content{max-width:1240px;margin:0 auto;padding:26px 32px 44px}
.page-head{margin-bottom:18px}
h1{margin:0;font-size:22px;line-height:1.2;font-weight:600;letter-spacing:-.022em}
.page-head p{margin:5px 0 0;font-size:12.5px;color:var(--muted);letter-spacing:.005em}

.card{
  background:var(--surface);
  border:1px solid var(--line);
  border-radius:var(--radius);
  box-shadow:0 1px 2px rgba(22,24,21,.035);
}

.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.kpi{padding:15px 17px 14px;display:flex;flex-direction:column;min-width:0}
.kpi-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:9px}
.kpi-label{font-size:11.5px;font-weight:500;color:var(--muted);letter-spacing:.005em;white-space:nowrap}
.kpi-head svg{width:16px;height:16px;color:#8b8f87;flex:none}
.kpi-value{
  display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;
  font-size:clamp(24px,2.1vw,30px);font-weight:600;line-height:1.1;
  letter-spacing:-.028em;color:var(--ink);
}
.delta{font-size:12px;font-weight:600;letter-spacing:-.005em;white-space:nowrap}
.delta.good{color:var(--good)}
.delta.bad{color:var(--bad)}
.kpi-foot{margin-top:auto;padding-top:9px;font-size:10.5px;color:var(--muted);white-space:nowrap}

.lower{
  display:grid;grid-template-columns:minmax(0,1.62fr) minmax(340px,1fr);
  gap:14px;margin-top:14px;align-items:stretch;
}
.card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}
.card-head h2{margin:0;font-size:14px;font-weight:600;letter-spacing:-.012em}
.card-head .sub{margin:3px 0 0;font-size:11.5px;color:var(--muted);letter-spacing:.005em}

.chart-card{padding:17px 20px 12px;display:flex;flex-direction:column;min-width:0}
.chart{
  --plot-h:240px;
  margin-top:16px;
  display:grid;
  grid-template-columns:36px minmax(0,1fr);
  grid-template-rows:var(--plot-h) 22px;
  column-gap:8px;row-gap:4px;
}
.y-axis{position:relative;grid-column:1;grid-row:1}
.y-axis span{
  position:absolute;right:0;transform:translateY(-50%);
  font-size:10px;color:var(--muted);font-variant-numeric:tabular-nums;letter-spacing:.01em;
}
.plot{position:relative;grid-column:2;grid-row:1;cursor:crosshair}
.gridlines{position:absolute;inset:0;pointer-events:none}
.gridlines i{position:absolute;left:0;right:0;height:1px;background:var(--grid)}
.gridlines i:last-child{background:var(--axis)}
.chart-svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.chart-area{fill:url(#areaGradient)}
.chart-line{
  fill:none;stroke:var(--brand);stroke-width:2;
  stroke-linecap:round;stroke-linejoin:round;
  vector-effect:non-scaling-stroke;
}
.point{
  position:absolute;width:24px;height:24px;margin:0;padding:0;border:0;
  background:none;transform:translate(-50%,-50%);
  display:grid;place-items:center;cursor:pointer;z-index:2;
}
.dot{
  width:8px;height:8px;border-radius:50%;background:var(--brand);
  box-shadow:0 0 0 2px var(--surface);
  transition:transform .12s ease;
}
.point:last-of-type .dot{
  width:10px;height:10px;
  box-shadow:0 0 0 2px var(--surface),0 0 0 4px rgba(47,111,94,.14);
}
.point:hover .dot,.point.is-active .dot{transform:scale(1.3)}
.point:focus-visible{outline:none}
.point:focus-visible .dot{box-shadow:0 0 0 2px var(--surface),0 0 0 4px var(--brand)}
.end-label{
  position:absolute;left:97.5%;top:calc(22% - 10px);
  transform:translate(-100%,-100%);
  z-index:3;pointer-events:none;white-space:nowrap;
  padding:3px 7px;border:1px solid var(--line-strong);border-radius:6px;
  background:var(--surface);color:var(--ink);
  font-size:10.5px;font-weight:600;font-variant-numeric:tabular-nums;
  box-shadow:0 1px 3px rgba(22,24,21,.07);
}
.crosshair{
  position:absolute;top:0;bottom:0;width:1px;
  background:#c9c4b8;opacity:0;z-index:1;pointer-events:none;
  transition:opacity .12s ease;
}
.crosshair.is-on{opacity:1}
.tip{
  position:absolute;z-index:6;display:flex;align-items:baseline;gap:6px;
  padding:5px 8px;border-radius:6px;background:var(--ink);color:#fff;
  box-shadow:0 4px 14px rgba(22,24,21,.2);
  opacity:0;visibility:hidden;pointer-events:none;white-space:nowrap;
  transition:opacity .1s ease,visibility .1s ease;
}
.tip.is-on{opacity:1;visibility:visible}
.tip-week{font-size:9.5px;color:rgba(255,255,255,.62);letter-spacing:.02em}
.tip-value{font-size:11.5px;font-weight:600;font-variant-numeric:tabular-nums}
.tip-unit{font-size:9.5px;color:rgba(255,255,255,.66)}
.x-axis{position:relative;grid-column:2;grid-row:2}
.x-axis span{
  position:absolute;top:4px;transform:translateX(-50%);
  font-size:10px;color:var(--muted);font-variant-numeric:tabular-nums;
}

.table-card{padding:17px 20px 14px;display:flex;flex-direction:column;min-width:0}
.table-wrap{margin-top:12px;flex:1}
table{width:100%;border-collapse:collapse;table-layout:fixed}
thead th{
  padding:0 0 9px;border-bottom:1px solid var(--line-strong);
  font-size:10.5px;font-weight:600;color:var(--muted);
  letter-spacing:.01em;text-align:left;
}
thead th.num{text-align:right}
thead th:first-child{width:46%}
thead th:nth-child(2){width:18%}
thead th:nth-child(3){width:18%}
thead th:nth-child(4){width:18%}
tbody tr{border-bottom:1px solid var(--line);transition:background-color .12s ease}
tbody tr:last-child{border-bottom:0}
tbody tr:hover{background:#faf9f6}
tbody th,tbody td{
  height:46px;padding:0;vertical-align:middle;
  font-size:12.5px;font-weight:400;color:var(--ink-2);
}
tbody th.event{
  font-family:var(--mono);font-size:11.5px;font-weight:500;color:var(--ink);
  letter-spacing:-.01em;text-align:left;padding-right:10px;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.num{text-align:right;font-variant-numeric:tabular-nums}
.trend-cell{text-align:right}
.trend{
  display:inline-flex;align-items:center;justify-content:center;
  width:22px;height:22px;border-radius:6px;
  font-size:12px;line-height:1;font-weight:600;
}
.trend.up{color:var(--good);background:var(--good-bg)}
.trend.down{color:var(--bad);background:var(--bad-bg)}

@media (max-width:1100px){
  .kpis{grid-template-columns:repeat(2,minmax(0,1fr))}
  .lower{grid-template-columns:1fr}
  .chart{--plot-h:250px}
}
@media (max-width:880px){
  .topbar-brand{width:auto;border-right:0;padding:0 0 0 16px}
  .topbar-tools{padding:0 16px 0 0;gap:8px}
  .sidebar{
    position:static;width:auto;height:auto;align-self:stretch;
    border-right:0;border-bottom:1px solid var(--line);
    padding:6px 8px;
  }
  .shell{display:block;min-height:0}
  .nav{flex-direction:row;height:auto;gap:2px}
  .nav-item{flex:1;justify-content:center;gap:6px;font-size:12px;padding:9px 4px;min-height:44px;white-space:nowrap}
  .nav-item svg{width:15px;height:15px}
  .nav-item.is-active::before{display:none}
  .nav-settings{margin-top:0}
  .content{padding:20px 20px 36px;max-width:none}
  .chart{--plot-h:230px}
}
@media (max-width:620px){
  .content{padding:16px 16px 32px}
  h1{font-size:20px}
  .page-head{margin-bottom:14px}
  .kpis{gap:10px}
  .kpi{padding:13px 14px 12px}
  .kpi-label{font-size:11px}
  .kpi-value{font-size:24px;gap:5px}
  .delta{font-size:11px}
  .kpi-foot{font-size:10px;padding-top:7px}
  .lower{gap:12px;margin-top:12px}
  .chart-card,.table-card{padding:15px 16px 12px}
  .chart{--plot-h:200px;grid-template-columns:32px minmax(0,1fr);column-gap:6px}
  .y-axis span,.x-axis span{font-size:9.5px}
  .end-label{font-size:10px;padding:2px 5px}
  tbody th.event{font-size:11px;padding-right:6px}
  tbody th,tbody td{height:44px;font-size:12px}
  .trend{width:21px;height:21px;border-radius:6px}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{transition:none!important}
}
